import { fetchEncryptStream, updStore, getStore, convertArray2Obj, ObjectKeys, callbackOnMemory, convertObj2Array, qryStore, fetchQueue, convertArray2ObjGroupby, isJson } from "../../../stores/Utils";




export const getall_deposit = async (cb) => {
    let lastTimeCallModal = getStore("getall_deposit_last") || 0;
    if(Date.now() > lastTimeCallModal){
        updStore("getall_deposit_last", Date.now()+190);
        let bdyq2 = {...getStore(qryStore())?.scan_deposit_summary};
        bdyq2.params = {
            businessId:  getStore("profileUser")?.businessId
        }
        const res = fetchEncryptStream(bdyq2);
        const td = await res;
        if (td) {
           
            updStore("deposits_list", sortDeposits(td,"depositDate"));
            updStore("deposits_ids", convertArray2Obj(convertObj2Array(td),"depositId"));
            cb && cb();
        }
    }
};




export const search_deposit = async (cb) => {

    let bdyq2 = {...getStore(qryStore())?.scan_deposit_summary};
    bdyq2.params = {
        businessId:  getStore("profileUser")?.businessId,
    }

    getStore("searchQryDept").split(" ").map((qry,inDq)=>{
        if(qry){
            bdyq2.params[":search"+inDq] = qry.trim();
        }
    })

    const res = fetchEncryptStream(bdyq2);
    const td = await res;

  
    if (td) {
        updStore("deposits_list", sortDeposits(convertObj2Array(td),"depositDate"));
        updStore("deposits_ids", td);
           
        cb && cb();
    }
    else{
        updStore("deposits_list", []);
    }
};





  
export const sortDeposits = (td, key, order) => {
        
		let sortedA = td && td.sort((a, b) => {
			let A = a[key];
			let B = b[key];
			if (A < B) {
				return order ? -1 : 1;
			}
			if (A > B) {
				return order ? 1 : -1;
			}
			return 0;
        });
		return sortedA;
	}






