const calc_comp_deposits =  () => {

    let depositCmp =  getStore("depositCmp");
    let CXC =  getStore("depositCmpSSJsgB2uUqcuoagD");
    let AntC =  getStore("depositCmpv5MkYLwPAbgci3wW");


    let docs = {

    }

    ObjectKeys(depositCmp).map(regId=>{
       
        let document = depositCmp[regId].document.trim();
       
        if(!docs[document]){
            docs[document] = {
                document: document,
                depositId: depositCmp[regId]?.depositId,
                depositLinkConfirmed: depositCmp[regId]?.depositLinkConfirmed,
                amount: 0,
                saldo: 0,
                hasAnticipo: 0,
                cc_c: 0,
                cc_d: 0,
                comprobanteIds: {}  
            }
        }
        docs[document]["amount"] += depositCmp[regId].amount;
        docs[document]["saldo"] += depositCmp[regId].amount *1;
        docs[document]["date"] = depositCmp[regId].date;
        //docs[document]["descriptionDeposit"] += depositCmp[regId].description;
    });
    ObjectKeys(CXC).map(regId=>{
        let document = CXC[regId].document.trim();
        if(!docs[document]){
            docs[document] = {
                document: document,
                amount: 0,
                saldo: 0,
                hasAnticipo: 0,
                cc_c: 0,
                cc_d: 0,
                comprobanteIds: {}   
            }
        }
        docs[document]["cc_d"] += CXC[regId]?.type === "debit"? CXC[regId].amount *1 : 0 ;
        docs[document]["cc_c"] += CXC[regId]?.type === "credit"? CXC[regId].amount *1 : 0 ;
        
        docs[document]["saldo"] += CXC[regId]?.type === "credit"? CXC[regId].amount *-1 : 0 ;
        docs[document]["comprobanteIds"][CXC[regId].comprobanteId] = {
            date: CXC[regId].date,
            description: CXC[regId].description
        };
    });
    ObjectKeys(AntC).map(regId=>{

       
        let document = AntC[regId].document.trim();
        if(document.indexOf("A-")>=0){
            document = document.split("A-")[1];
        }
        if(!docs[document]){
            docs[document] = {
                document: document,
                amount: 0,
                hasAnticipo: 0,
                cc_c: 0,
                cc_d: 0,
                saldo: 0,
                comprobanteIds: {}   
            }
        }
        docs[document]["hasAnticipo"] += AntC[regId]?.type === "credit"? AntC[regId].amount *1 : AntC[regId].amount *-1 ;
        docs[document]["saldo"] += (AntC[regId]?.type === "credit"? AntC[regId].amount *1 : AntC[regId].amount *-1 ) *-1;
        docs[document]["comprobanteIds"][AntC[regId].comprobanteId] = {
            date: AntC[regId].date,
            description: AntC[regId].description
        };
    });
   
    return docs;
}












