export const loadDepositsfromFile = async (fileJSON) => {
    let bdyq2 = {...getStore(qryStore())?.all_deposit_summary};
    bdyq2.params = {
        businessId:  getStore("profileUser")?.businessId,
        ":search1": "  " 
    }
    const res = fetchEncryptStream(bdyq2);
    const td = await res;

    if (td) {

        let prod = [];

        let docM = convertArray2ObjGroupby(td,"id")

        if(isJson(fileJSON)){
            fileJSON = JSON.parse(fileJSON)
        }

        fileJSON.map(dpt=>{
            let nfrm = {...dpt}
            nfrm.depositSummaryId = dpt.id;
            let isN = !docM[dpt.id];


            let ignArr = {}
            // ignArr = {"51320487895":1}

            
            if(ignArr[dpt.id]){
                    isN = true
            }
            
           
            let hasTR = dpt?.transactions.length>0;
	        
           
            if( dpt.id && dpt.amount &&  dpt.paymentDepositFee && isN && hasTR){
                let bdyq23 = {...getStore(qryStore())?.add_deposit_summary};
                bdyq23.params = {
                    businessId:  getStore("profileUser")?.businessId
                };
                bdyq23.form = nfrm;

                prod.push(bdyq23) 
            }
            
        })
        //console.log(prod)
        fetchQueue(prod, fetchCSVInve)
    }
        
   
}

export const fetchCSVInve = async (qry2Sv) => {
    const res = fetchEncryptStream(qry2Sv);
    const td = await res;
    if (td) {
        return td;
    }
}
