import React, { useEffect, useState, useRef } from "react";

import { getStore,  gen16CodeId, ObjectKeys, AccountYears, setIntervalX} from "../../../stores/Utils";

import {CheckBoxSlide_Cmpt, SearchInput_Cmpt } from "../../../components";

import { OpenModal } from "../../../components/DialogHRM";

import "./dashboard.css"
import "./styles.css"
import { DepositSummaryItem_Cmpt, AddDeposit_Cmpt, ViewPrintCheck_Cmpt, DepositFeeView } from "..";
import {  getall_deposit, loadDepositsfromFile, search_deposit } from "../services/server_fetching";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import { scan_location_production } from "../../Inventory/services/server_fetching";
import { GrayButton } from "../../../components/Buttons";


const SearchInput = SearchInput_Cmpt();

const CheckBoxSlide = CheckBoxSlide_Cmpt();

const DepositItem = DepositSummaryItem_Cmpt();






const DepositSummaryDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const [range, set_range] = useState(64);
	const [viewFee, setViewFee] = useState(false);

	const [loading, set_loading] = useState(false);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			// getall_deposit(loadList);
			scan_location_production(updObs);
			get_balances_by_type("global_accounts","global_account_params",updObs);
		}
	});


	const openUpdateView =  () => {
		
	}

	const handleChange =  (v) => {
		!loading && set_loading(true)
	}

	const handle_search_deposit =  (v) => {
		set_loading(true)
		search_deposit(loadList)
	}


	const handle_getall_deposit =  (v) => {
		getall_deposit(loadList)
	}

	const cb_result1 = async (f, v) => {
		set_obs(gen16CodeId())
		
	};




	const openSaleView =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		
		loadDepositsfromFile()
		//OpenModal(dataModal);
	}


	const openCompareView =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		
		OpenModal(dataModal);
	}

	
	const openCheckView =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		
		
		OpenModal(dataModal);
	}

	const cb_result = async (f, v) => {
		if(range!==64){
			set_range(64);
		}
		else{
			set_obs(gen16CodeId())
		}
		set_loading(false);
	};
	
	const loadMore=  () => {
		set_range(v=>v+64)
	}

	const loadList =  () => {

		
		cb_result();

		let factor = Math.ceil(ObjectKeys(getStore("deposits_list"))?.length / 64);

		setIntervalX(loadMore, 1250, factor)

		setTimeout(() => {
			set_loading(false)
		}, 230);
		
	};
	


	
	const importCSV =  (event) => {
		var fileReader = new FileReader();
		fileReader.onload = function(fileLoadedEvent){
			var textFromFileLoaded = fileLoadedEvent.target.result;
			loadDepositsfromFile(textFromFileLoaded)
		
		};
	  
		fileReader.readAsText(event.target.files[0], "UTF-8");
	}

	
	const addFee2AccountBook = () => {
		let depositFeeSelected = getStore("depositFeeSelected") || {};
		let descripcion = "fee for deposit Ids"
		let paymentDepositFee = 0;
		ObjectKeys(depositFeeSelected).map(dpId=>{
			paymentDepositFee += depositFeeSelected[dpId];
			descripcion +=` ${dpId};`
		})

		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		modaldata["content"] =  <DepositFeeView confirm={handle_getall_deposit} 
		description={descripcion}
		feeAmount={paymentDepositFee}
		item={data}/>
		OpenModal(modaldata);
	}


	return (

	<div className="">
		<div className="accounts_header">
			<h2>Deposits</h2>
			<div className="_dsplFlx ">
				<div className="group_title addBtn purple upl">
					Import Deposits from File
					<input id="fileupload" type = "file" onChange={importCSV}/>
				</div>
				<div className="flexSpace"/>
				<div className="_dsplFlx centerBx" >
					<span className={`checklabel`}>
						{"Add Fee"}
					</span>
					<CheckBoxSlide
						initvalue={viewFee}
						keyCode={57}
						updChange={setViewFee}
					/>
				</div>
				<div className="_dsplFlx " style={{marginLeft:14}} >
				{viewFee?
				<GrayButton color={"#007bfc"} label={"Add Fee "} clickHandler={addFee2AccountBook}/>
				:null}
				</div>
			</div>
			<div className="_dsplFlx " style={{marginTop:14}} >
				<SearchInput
					placeholder={"Buscar ...."} 
					width={360}
					obs={set_obs}
					fetchData={handle_search_deposit}
					loading={loading}
					change={handleChange}
					callempty={handle_getall_deposit}
					keyFlds={"searchQryDept"}
				/>
				<div className="flexSpace"/>
				<div className="_dsplFlx ">
					<div className="total_comprobante_title">
						No de Deposits: 
					</div>
					<div className="total_comprobante gray">
						<span>
							{ObjectKeys(getStore("deposits_list"))?.length}
						</span>
					</div>
					
				</div>
			</div>
		</div>
		

		<div className="deposits_container scollVh" style={{height: "calc(98vh - 230px)"}}>
			{getStore("deposits_list") && ObjectKeys(getStore("deposits_list"))?.map((cid, index)=>{
				return (
					<DepositItem 
						data={getStore("deposits_list")[cid]} 
						elmId={cid} 
						key={cid}
						openUpdateView={openUpdateView}
						handleRefreshAll={handle_getall_deposit}
						show={index < range}
						index={index}
						viewFee={viewFee}
					/>
				)
			})}
		</div>
		</div>
	);
};

export default DepositSummaryDashboard;



